const path = require("path");
const encode = require("./encode");

const imageRegex = /url\((.*?)\)/g;

module.exports = function (str, file) {
    const hexo = this;
    const config = hexo.config.filter_base64;
    const cssPath = path.dirname(file.path);

    let matches;
    let newStr = str;

    if (config.enabled) {
        while (matches = imageRegex.exec(str)) {
            const match = matches[1];
            const src = match.replace(/"/g, '');

            if (!/^(data|http:\/\/|https:\/\/)/.test(src)) {
                const filePath = path.resolve(cssPath, src);
                const encoded = encode(filePath, hexo);
                if (encoded) newStr = newStr.replace(matches[0], `url("${encoded}")`);
            }
        }
    }

    return newStr;
};
